"""SCPD and SOAP dispatch generated by the pinned device stack, not static claims."""
import xml.etree.ElementTree as ET

from async_upnp_client.const import DeviceInfo, ServiceInfo
from async_upnp_client.server import (
    UpnpServerDevice, UpnpServerService, callable_action, create_state_var, create_event_var,
)

from .runtime import udn


# Each advertised action has a concrete dispatch implementation in runtime.Room.
# State-variable types are also used by the stack to validate input/output SOAP.
AV_VARS = {
    'InstanceID': 'ui4', 'TransportState': 'string', 'TransportStatus': 'string',
    'TransportPlaySpeed': 'string', 'AVTransportURI': 'string', 'AVTransportURIMetaData': 'string',
    'NextAVTransportURI': 'string', 'NextAVTransportURIMetaData': 'string',
    'NumberOfTracks': 'ui4', 'CurrentTrack': 'ui4', 'CurrentTrackDuration': 'string',
    'CurrentMediaDuration': 'string', 'CurrentTrackMetaData': 'string', 'CurrentTrackURI': 'string',
    'RelativeTimePosition': 'string', 'AbsoluteTimePosition': 'string',
    'RelativeCounterPosition': 'i4', 'AbsoluteCounterPosition': 'i4',
    'PlaybackStorageMedium': 'string', 'RecordStorageMedium': 'string', 'RecordMediumWriteStatus': 'string',
    'PossiblePlaybackStorageMedia': 'string', 'PossibleRecordStorageMedia': 'string',
    'PossibleRecordQualityModes': 'string', 'CurrentRecordQualityMode': 'string',
    'CurrentPlayMode': 'string', 'CurrentTransportActions': 'string',
    'SeekMode': 'string', 'SeekTarget': 'string',
}
AV_ACTIONS = {
    'SetAVTransportURI': ({'InstanceID': 'InstanceID', 'CurrentURI': 'AVTransportURI', 'CurrentURIMetaData': 'AVTransportURIMetaData'}, {}),
    'Play': ({'InstanceID': 'InstanceID', 'Speed': 'TransportPlaySpeed'}, {}),
    'Pause': ({'InstanceID': 'InstanceID'}, {}), 'Stop': ({'InstanceID': 'InstanceID'}, {}),
    'Seek': ({'InstanceID': 'InstanceID', 'Unit': 'SeekMode', 'Target': 'SeekTarget'}, {}),
    'GetTransportInfo': ({'InstanceID': 'InstanceID'}, {'CurrentTransportState': 'TransportState', 'CurrentTransportStatus': 'TransportStatus', 'CurrentSpeed': 'TransportPlaySpeed'}),
    'GetPositionInfo': ({'InstanceID': 'InstanceID'}, {'Track': 'CurrentTrack', 'TrackDuration': 'CurrentTrackDuration', 'TrackMetaData': 'CurrentTrackMetaData', 'TrackURI': 'CurrentTrackURI', 'RelTime': 'RelativeTimePosition', 'AbsTime': 'AbsoluteTimePosition', 'RelCount': 'RelativeCounterPosition', 'AbsCount': 'AbsoluteCounterPosition'}),
    'GetMediaInfo': ({'InstanceID': 'InstanceID'}, {'NrTracks': 'NumberOfTracks', 'MediaDuration': 'CurrentMediaDuration', 'CurrentURI': 'AVTransportURI', 'CurrentURIMetaData': 'AVTransportURIMetaData', 'NextURI': 'NextAVTransportURI', 'NextURIMetaData': 'NextAVTransportURIMetaData', 'PlayMedium': 'PlaybackStorageMedium', 'RecordMedium': 'RecordStorageMedium', 'WriteStatus': 'RecordMediumWriteStatus'}),
    'GetDeviceCapabilities': ({'InstanceID': 'InstanceID'}, {'PlayMedia': 'PossiblePlaybackStorageMedia', 'RecMedia': 'PossibleRecordStorageMedia', 'RecQualityModes': 'PossibleRecordQualityModes'}),
    'GetTransportSettings': ({'InstanceID': 'InstanceID'}, {'PlayMode': 'CurrentPlayMode', 'RecQualityMode': 'CurrentRecordQualityMode'}),
    'SetPlayMode': ({'InstanceID': 'InstanceID', 'NewPlayMode': 'CurrentPlayMode'}, {}),
    'GetCurrentTransportActions': ({'InstanceID': 'InstanceID'}, {'Actions': 'CurrentTransportActions'}),
}
RC_VARS = {'InstanceID': 'ui4', 'Channel': 'string', 'Volume': 'ui2', 'Mute': 'boolean',
           'PresetName': 'string', 'PresetNameList': 'string'}
RC_ACTIONS = {
    'GetVolume': ({'InstanceID': 'InstanceID', 'Channel': 'Channel'}, {'CurrentVolume': 'Volume'}),
    'SetVolume': ({'InstanceID': 'InstanceID', 'Channel': 'Channel', 'DesiredVolume': 'Volume'}, {}),
    'GetMute': ({'InstanceID': 'InstanceID', 'Channel': 'Channel'}, {'CurrentMute': 'Mute'}),
    'SetMute': ({'InstanceID': 'InstanceID', 'Channel': 'Channel', 'DesiredMute': 'Mute'}, {}),
    'ListPresets': ({'InstanceID': 'InstanceID'}, {'CurrentPresetNameList': 'PresetNameList'}),
    'SelectPreset': ({'InstanceID': 'InstanceID', 'PresetName': 'PresetName'}, {}),
}
CM_VARS = {'SourceProtocolInfo': 'string', 'SinkProtocolInfo': 'string', 'CurrentConnectionIDs': 'string',
           'ConnectionID': 'i4', 'RcsID': 'i4', 'AVTransportID': 'i4', 'ProtocolInfo': 'string',
           'ConnectionManager': 'string', 'Direction': 'string', 'ConnectionStatus': 'string'}
CM_ACTIONS = {
    'GetProtocolInfo': ({}, {'Source': 'SourceProtocolInfo', 'Sink': 'SinkProtocolInfo'}),
    'GetCurrentConnectionIDs': ({}, {'ConnectionIDs': 'CurrentConnectionIDs'}),
    'GetCurrentConnectionInfo': ({'ConnectionID': 'ConnectionID'}, {'RcsID': 'RcsID', 'AVTransportID': 'AVTransportID', 'ProtocolInfo': 'ProtocolInfo', 'PeerConnectionManager': 'ConnectionManager', 'PeerConnectionID': 'ConnectionID', 'Direction': 'Direction', 'Status': 'ConnectionStatus'}),
}


def service_class(name, variables, actions):
    definitions = {key: create_state_var(kind) for key, kind in variables.items()}
    if name != 'ConnectionManager':
        definitions['LastChange'] = create_event_var('string', default='')
    else:
        for key in ('SourceProtocolInfo', 'SinkProtocolInfo', 'CurrentConnectionIDs'):
            definitions[key] = create_event_var('string', default='')
    if name == 'RenderingControl':
        definitions['Channel'] = create_state_var('string', allowed=['Master'])
        definitions['Volume'] = create_state_var('ui2', allowed_range={'minimum': '0', 'maximum': '100', 'step': '1'})
    attrs = {
        'STATE_VARIABLE_DEFINITIONS': definitions,
        'SERVICE_DEFINITION': ServiceInfo(f'urn:upnp-org:serviceId:{name}',
            f'urn:schemas-upnp-org:service:{name}:1', f'/{name}/control', f'/{name}/event', f'/{name}/scpd.xml', ET.Element('service')),
    }
    for action, (inputs, outputs) in actions.items():
        def make_handler(action, inputs):
            async def handle(self, **kwargs):
                return await self.device.room.call(action, **kwargs)
            handle.__annotations__ = {arg: bool if variables[var] == 'boolean' else
                int if variables[var] in {'ui4', 'ui2', 'i4'} else str for arg, var in inputs.items()}
            return handle
        attrs[action] = callable_action(action, inputs, outputs)(make_handler(action, inputs))
    return type(name, (UpnpServerService,), attrs)


AVTransport = service_class('AVTransport', AV_VARS, AV_ACTIONS)
RenderingControl = service_class('RenderingControl', RC_VARS, RC_ACTIONS)
ConnectionManager = service_class('ConnectionManager', CM_VARS, CM_ACTIONS)


def device_class(room, bridge_id):
    class Renderer(UpnpServerDevice):
        DEVICE_DEFINITION = DeviceInfo(
            device_type='urn:schemas-upnp-org:device:MediaRenderer:1',
            friendly_name=room.config['name'] + ' DLNA', manufacturer='Community Bridge',
            manufacturer_url=None, model_description='Experimental logical Raumfeld room bridge',
            model_name='Logical Room DLNA Bridge', model_number='1', model_url=None,
            serial_number=None, udn=udn(bridge_id, room.config['id']), upc=None,
            presentation_url=None, url='/device.xml', icons=[], xml=ET.Element('device'))
        EMBEDDED_DEVICES = []
        SERVICES = [AVTransport, RenderingControl, ConnectionManager]

        def __init__(self, *args, **kwargs):
            self.room = room
            super().__init__(*args, **kwargs)
            room.changed = self.publish
            self.publish()

        def publish(self):
            avt = self.service('urn:schemas-upnp-org:service:AVTransport:1')
            rcs = self.service('urn:schemas-upnp-org:service:RenderingControl:1')
            cm = self.service('urn:schemas-upnp-org:service:ConnectionManager:1')
            for service, namespace, fields in [
                (avt, 'AVT', {'TransportState': room.transport, 'TransportStatus': room.status,
                    'AVTransportURI': room.uri, 'AVTransportURIMetaData': room.metadata,
                    'CurrentTrackURI': room.uri, 'CurrentTrackMetaData': room.metadata,
                    'CurrentTrackDuration': room.duration, 'RelativeTimePosition': room.position,
                    'CurrentTrack': '1' if room.uri else '0', 'NumberOfTracks': '1' if room.uri else '0'}),
                (rcs, 'RCS', {key: str(int(value)) for key, value in
                    [('Volume', room.volume), ('Mute', room.mute)] if value is not None}),
            ]:
                root = ET.Element('Event', xmlns=f'urn:schemas-upnp-org:metadata-1-0/{namespace}/')
                instance = ET.SubElement(root, 'InstanceID', val='0')
                for key, value in fields.items():
                    ET.SubElement(instance, key, val=str(value), **({'channel': 'Master'} if namespace == 'RCS' else {}))
                service.state_variable('LastChange').value = ET.tostring(root, encoding='unicode')
            cm.state_variable('SourceProtocolInfo').value = ''
            cm.state_variable('SinkProtocolInfo').value = room.sink
            cm.state_variable('CurrentConnectionIDs').value = '0' if room.loaded_uri else ''

    return Renderer
